// src/pages/Mesas.jsx → VERSIÓN DIOS con RESERVAS + CANTIDAD EXACTA
import { useEffect, useState } from "react";
import { api } from "../services/api";
import { Table, Users, Clock, Trash2, Calendar } from "lucide-react";
import "./Mesas.css";

export default function Mesas() {
  const [mesas, setMesas] = useState([]);
  const [loading, setLoading] = useState(true);

  // Modales
  const [showModal, setShowModal] = useState(false);
  const [mesaSeleccionada, setMesaSeleccionada] = useState(null);
  const [cantidadClientes, setCantidadClientes] = useState(1);
  const [nombreReserva, setNombreReserva] = useState("");
  const [modoModal, setModoModal] = useState("ocupar"); // "ocupar" | "reservar"

  const [showLiberarTodas, setShowLiberarTodas] = useState(false);

  useEffect(() => {
    cargarMesas();
  }, []);

  const cargarMesas = async () => {
    try {
      const data = await api.get("/api/mesas/");
      setMesas(data.map(m => ({
        ...m,
        reservada_para: m.reservada_para || null,
        nombre_reserva: m.nombre_reserva || null
      })));
    } catch (err) {
      alert("Error cargando mesas (¿sesión expirada?)");
    } finally {
      setLoading(false);
    }
  };

  const abrirModal = (mesa, modo = "ocupar") => {
    setMesaSeleccionada(mesa);
    setModoModal(modo);
    setCantidadClientes(mesa.clientes_actuales || mesa.capacidad);
    setNombreReserva(mesa.nombre_reserva || "");
    setShowModal(true);
  };

  const confirmarAccion = async () => {
    if (!mesaSeleccionada) return;

    try {
      if (modoModal === "ocupar") {
        if (mesaSeleccionada.ocupada || mesaSeleccionada.reservada_para) {
          // Liberar o cancelar reserva
          await api.post(`/api/mesas/${mesaSeleccionada.id}/liberar/`);
        } else {
          // Ocupar con cantidad exacta
          await api.post(`/api/mesas/${mesaSeleccionada.id}/ocupar/`, {
            cantidad_clientes: cantidadClientes
          });
        }
      } else if (modoModal === "reservar") {
        await api.post(`/api/mesas/${mesaSeleccionada.id}/reservar/`, {
          nombre_reserva: nombreReserva || "Reserva"
        });
      }
      cargarMesas();
    } catch (err) {
      alert("Error al procesar");
    }
    setShowModal(false);
  };

  const liberarTodas = async () => {
    for (const m of mesas.filter(m => m.ocupada || m.reservada_para)) {
      await api.post(`/api/mesas/${m.id}/liberar/`);
    }
    cargarMesas();
    setShowLiberarTodas(false);
  };

  const ocupadas = mesas.filter(m => m.ocupada).length;
  const reservadas = mesas.filter(m => m.reservada_para).length;
  const libres = mesas.length - ocupadas - reservadas;

  if (loading) return <div className="loader">Cargando...</div>;

  return (
    <div className="mesas-page god-mode">
      <div className="mesas-bg"></div>
      <div className="mesas-overlay"></div>

      {/* BARRA SUPERIOR ÉPICA */}
      <div className="stats-bar">
        <div className="stat"><Users size={40} color="#e74c3c" /><div><span className="numero">{ocupadas}</span><span className="texto">Ocupadas</span></div></div>
        <div className="stat"><Calendar size={40} color="#f39c12" /><div><span className="numero">{reservadas}</span><span className="texto">Reservadas</span></div></div>
        <div className="stat"><Table size={40} color="#10b981" /><div><span className="numero">{libres}</span><span className="texto">Libres</span></div></div>
        <button onClick={() => setShowLiberarTodas(true)} className="btn-liberar-todas"><Trash2 size={20} /> Liberar todas</button>
      </div>

      <div className="mesas-content">
        <h1 className="mesas-title">CONTROL DE MESAS</h1>
        <p className="mesas-subtitle">
          Click → ocupar/liberar rápido | Click derecho → opciones avanzadas
        </p>

        <div className="mesas-grid">
          {mesas.map((mesa) => {
            const esOcupada = mesa.ocupada;
            const esReservada = mesa.reservada_para;
            let color = "#10b981";
            let estado = "LIBRE";
            let Icon = Table;

            if (esOcupada) { color = "#e74c3c"; estado = "OCUPADA"; Icon = Users; }
            else if (esReservada) { color = "#f39c12"; estado = "RESERVADA"; Icon = Calendar; }

            return (
              <div
                key={mesa.id}
                className={`mesa-card pro ${esOcupada ? "pulse" : ""}`}
                onClick={() => esOcupada || esReservada ? confirmarAccion() : abrirModal(mesa, "ocupar")}
                onContextMenu={(e) => {
                  e.preventDefault();
                  abrirModal(mesa, esReservada ? "ocupar" : "reservar");
                }}
                style={{ "--estado-color": color }}
              >
                <div className="mesa-header">
                  <Icon size={44} />
                  <span className="mesa-numero">Mesa {mesa.numero}</span>
                </div>
                <div className="mesa-body">
                  <div className="estado-badge pro"><div className="punto"></div><span style={{ color }}>{estado}</span></div>
                  <p className="capacidad">Capacidad: {mesa.capacidad}</p>
                  <p className="clientes-grande">{mesa.clientes_actuales || 0} / {mesa.capacidad}</p>
                  {esReservada && <div className="reserva-nombre">{mesa.nombre_reserva}</div>}
                  {esOcupada && <div className="tiempo-ocupada"><Clock size={16} /> Reciente</div>}
                </div>
                <div className="mesa-glow"></div>
              </div>
            );
          })}
        </div>
      </div>

      {/* MODAL PRINCIPAL */}
      {showModal && mesaSeleccionada && (
        <div className="modal-overlay" onClick={() => setShowModal(false)}>
          <div className="modal" onClick={e => e.stopPropagation()}>
            <h2>Mesa {mesaSeleccionada.numero}</h2>
            {modoModal === "ocupar" ? (
              mesaSeleccionada.ocupada || mesaSeleccionada.reservada_para ? (
                <p>¿Liberar esta mesa?</p>
              ) : (
                <>
                  <p>¿Cuántas personas se sientan?</p>
                  <input type="number" min="1" max={mesaSeleccionada.capacidad} value={cantidadClientes}
                    onChange={e => setCantidadClientes(Number(e.target.value))} className="input-clientes" />
                </>
              )
            ) : (
              <>
                <p>Reservar mesa para:</p>
                <input type="text" placeholder="Nombre del cliente" value={nombreReserva}
                  onChange={e => setNombreReserva(e.target.value)} className="input-clientes" />
              </>
            )}
            <div className="modal-buttons">
              <button onClick={confirmarAccion} className="btn-confirmar">Confirmar</button>
              <button onClick={() => setShowModal(false)} className="btn-cancelar">Cancelar</button>
            </div>
          </div>
        </div>
      )}

      {/* MODAL LIBERAR TODAS */}
      {showLiberarTodas && (
        <div className="modal-overlay" onClick={() => setShowLiberarTodas(false)}>
          <div className="modal" onClick={e => e.stopPropagation()}>
            <h2>¿Liberar TODAS las mesas?</h2>
            <p>Incluye reservas y mesas ocupadas.</p>
            <div className="modal-buttons">
              <button onClick={liberarTodas} className="btn-confirmar">Sí, liberar todas</button>
              <button onClick={() => setShowLiberarTodas(false)} className="btn-cancelar">Cancelar</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
